plugins {
    alias(libs.plugins.android.library)
    alias(libs.plugins.kotlin.serialization)
}

android {
    namespace = "com.zephyr.engine"
    compileSdk = 37
    defaultConfig {
        minSdk = 28
        consumerProguardFiles("consumer-rules.pro")
    }
    compileOptions {
        sourceCompatibility = JavaVersion.VERSION_17
        targetCompatibility = JavaVersion.VERSION_17
    }
    testOptions { unitTests.isReturnDefaultValues = true }
    // UniFFI bindings are generated by Agent-A into core-mobile/bindings (read-only here, never hand-edited).
    sourceSets["main"].kotlin.srcDir(rootProject.file("../../core-mobile/bindings/kotlin"))
    // Per-ABI libzephyr_mobile_core.so built by :core-engine:cargoBuild (or CI) lands here.
    sourceSets["main"].jniLibs.srcDir(layout.buildDirectory.dir("rustJniLibs").get().asFile)
}

dependencies {
    api(libs.kotlinx.coroutines.core)
    implementation(libs.kotlinx.serialization.json)
    implementation("${libs.jna.get()}@aar")
    testImplementation(libs.jna)
    testImplementation(libs.junit)
    testImplementation(kotlin("test"))
    testImplementation(libs.kotlinx.coroutines.test)
}

// Contract fixtures live at repo root; tests read them via this system property.
tasks.withType<Test>().configureEach {
    systemProperty("zephyr.fixtures", rootProject.file("../../contract/fixtures").absolutePath)
    systemProperty("zephyr.coreLib", providers.gradleProperty("zephyr.coreLib").orNull ?: "")
    maxHeapSize = "2g"
}

// ── Rust core (core-mobile) → jniLibs ─────────────────────────────────────────────────────────────
// Opt-in: ./gradlew -Pzephyr.rust=true assembleDebug  (needs cargo + cargo-ndk + NDK). Without it the
// app ships no .so and CoreEngine transparently stays on MockEngine.
val rustAbis = mapOf("arm64-v8a" to "aarch64-linux-android", "x86_64" to "x86_64-linux-android")
val cargoBuild by tasks.registering(Exec::class) {
    val crate = rootProject.file("../../core-mobile")
    val out = layout.buildDirectory.dir("rustJniLibs").get().asFile
    workingDir = crate
    inputs.dir(crate.resolve("src")); inputs.file(crate.resolve("Cargo.toml"))
    outputs.dir(out)
    commandLine(
        listOf("cargo", "ndk", "--platform", "28", "-o", out.absolutePath) +
            rustAbis.keys.flatMap { listOf("-t", it) } + listOf("build", "--release", "--lib"),
    )
}
if (providers.gradleProperty("zephyr.rust").orNull == "true") {
    tasks.matching { it.name.startsWith("merge") && it.name.endsWith("JniLibFolders") }.configureEach { dependsOn(cargoBuild) }
}
